import json
from pathlib import Path
root=Path(__file__).resolve().parents[1];c=json.loads((root/'data/campus.json').read_text())
ids=[444988443,445696811,383447316,382867984,382867991,444864794,444867698,444867699,444867700,444867704,444988684,444988685,445696812,445696814,445696816,445696825,445696826,565159270]
notes=['歸燕食巢詠霽路側','大門往師大路中央長步道','霽遠樓南側長步道','歸燕食巢舊入口連接','霽遠樓南側短段','圖資大樓南側連接','致理東側連接甲','致理東側連接乙','致理東側連接丙','高斯東側連接','中央坡地環繞步道','歸燕食巢東北短段','師大路一段西側短連接','師大路一二段交會連接','師大路二段北端連接','生科與球場西側步道','生科與球場東側步道','圖資東南連接']
previous={i['id']:i for i in json.loads((root/'docs/footpath-review.json').read_text()).get('items',[])} if (root/'docs/footpath-review.json').exists() else {}
items=[]
for i,(id,note) in enumerate(zip(ids,notes)):
 key=f'W{i+1:02}';prior=previous.get(key,{});r=next((r for r in c['roads'] if r['osm']==id),prior.get('sourceRoad'));assert r, f'Missing review source for {key}';items.append({**prior,'id':key,'osm':id,'note':note,'line':r['line'],'status':prior.get('status','pending')})
data=json.dumps({'roads':c['roads'],'buildings':c['places']+c['buildings'],'boundary':c['boundary'],'items':items},ensure_ascii=False,separators=(',',':'))
html='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>步道保留與移除核對</title><style>body{font:16px system-ui;margin:16px;background:#f2f4ee;color:#183640}main{display:flex;gap:16px;flex-wrap:wrap}svg{background:#c4d2b6;width:min(100%,650px);height:75vh;border:1px solid #9aa;touch-action:auto}aside{max-width:430px}button{display:block;padding:10px;text-align:left;width:100%;margin:5px 0;border:1px solid #b4c0bd;border-radius:7px;background:white;color:#183640}.active{background:#ffe39a}p{line-height:1.6}</style><h1>步道核對圖</h1><p>橘色為待確認步道，灰色虛線為已移除路線的歷史定位，深色為建築。點選編號放大定位；已移除步道不再出現在遊戲中。部分路線只有一段鄰近人行道，請回覆編號及「整條移除／僅移除重複段／保留」。名稱為定位說明，並非官方路名。</p><button id="reset">顯示全校</button><main><svg viewBox="-400 -550 800 1130" aria-label="步道核對地圖"></svg><aside></aside></main><script>const d=DATA,svg=document.querySelector('svg'),aside=document.querySelector('aside'),ns='http://www.w3.org/2000/svg';function el(tag,attrs,text){const e=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;svg.append(e);return e}const line=p=>p.map(a=>a.join(',')).join(' ');for(const r of d.roads)el('polyline',{points:line(r.line),fill:'none',stroke:r.width>2.5?'#626e70':'#a7a892','stroke-width':r.width,'stroke-linecap':'round'});for(const b of d.buildings){el('polygon',{points:line(b.ring),fill:'#4f6c77'});if(b.name){let x=b.ring.reduce((s,p)=>s+p[0],0)/b.ring.length,z=b.ring.reduce((s,p)=>s+p[1],0)/b.ring.length;el('text',{x,y:z,'font-size':11,fill:'#10333f',stroke:'white','stroke-width':2,'paint-order':'stroke','text-anchor':'middle'},b.name)}}el('text',{x:-380,y:-510,'font-size':24},'N ↑');const paths=[];for(const item of d.items){const p=el('polyline',{points:line(item.line),fill:'none',stroke:item.status==='removed'?'#78817e':'#c57617','stroke-dasharray':item.status==='removed'?'4 4':'none','stroke-width':3,'stroke-linecap':'round'});paths.push(p);const mid=item.line[Math.floor(item.line.length/2)];el('text',{x:mid[0],y:mid[1]-4,'font-size':13,'font-weight':800,fill:'#8e2800',stroke:'white','stroke-width':3,'paint-order':'stroke'},item.id);const b=document.createElement('button');b.textContent=item.id+' '+item.note+(item.status==='removed'?'（已移除）':'');b.onclick=()=>{document.querySelectorAll('aside button').forEach(e=>e.classList.remove('active'));b.classList.add('active');paths.forEach(e=>e.setAttribute('stroke-width',3));p.setAttribute('stroke-width',6);svg.append(p);const xs=item.line.map(p=>p[0]),zs=item.line.map(p=>p[1]),w=Math.max(100,Math.max(...xs)-Math.min(...xs)+70),h=Math.max(100,Math.max(...zs)-Math.min(...zs)+70);svg.setAttribute('viewBox',[(Math.max(...xs)+Math.min(...xs)-w)/2,(Math.max(...zs)+Math.min(...zs)-h)/2,w,h].join(' '))};aside.append(b)}document.querySelector('#reset').onclick=()=>svg.setAttribute('viewBox','-400 -550 800 1130');</script></html>'''.replace('DATA',data)
if all(i['status']=='removed' for i in items):html=html.replace('部分路線只有一段鄰近人行道，請回覆編號及「整條移除／僅移除重複段／保留」。','W01–W18 已全數確認移除；本頁僅保留歷史定位。')
(root/'footpaths.html').write_text(html);(root/'docs/footpath-review.json').write_text(json.dumps({'status':'confirmed' if all(i['status']=='removed' for i in items) else ('partially-confirmed' if any(i['status']!='pending' for i in items) else 'pending-user-confirmation'),'items':items},ensure_ascii=False,indent=2)+'\n');print('Built read-only review of',len(items),'footpaths; confirmed removals:',sum(i['status']=='removed' for i in items))
